def opened(app, wait=3.0):
    """The VJ run until the sources its decks want have opened (on workers) and are in the pool."""
    end = time.time() + wait
    vj.update(app, 1 / 40)
    while time.time() < end and vj_state.of(app).opening:
        time.sleep(0.01)
        vj.update(app, 1 / 40)
    vj.update(app, 1 / 40)


