ref = (img[y0, x0] * (1 - fx) + img[y0, x1] * fx) * (1 - fy) + (img[y1, x0] * (1 - fx) + img[y1, x1] * fx) * fy
check(s.dtype == np.float32 and s.shape == (11, 17, 3) and np.abs(s - ref).max() < 1e-5, "sample stays float32, bilinear")
